    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0xFCFD80E86E0B655BULL + 0xAFC0D4A148FDE101ULL);
