            aOrbiterA = (aWandererA + RotL64(aIngress, 51U)) + 0x9E8980D72ED6ED01ULL;
            aOrbiterD = (aWandererJ + RotL64(aPrevious, 39U)) + 0x261CD8F81758F68FULL;
            aOrbiterC = ((aWandererB + RotL64(aCross, 35U)) + RotL64(aCarry, 37U)) + 0x54A59356E0AE5A8AULL;
