            //
            aIngress = (RotL64(aWindLaneA[((aIndex + 4203U)) & S_BLOCK1], 50U) ^ RotL64(aWindLaneB[((aIndex + 1249U)) & S_BLOCK1], 29U));
            aIngress ^= (RotL64(aPlasmaLaneB[((aIndex + 757U)) & S_BLOCK1], 11U) ^ RotL64(aWoodLaneB[((S_BLOCK1 - aIndex + 4665U)) & S_BLOCK1], 19U));
            aIngress = TwistMix64::DiffuseB((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneC[((S_BLOCK1 - aIndex + 7861U)) & S_BLOCK1], 41U) ^ RotL64(aShadowLaneA[((S_BLOCK1 - aIndex + 2333U)) & S_BLOCK1], 12U));
            aCross ^= (RotL64(aShadowLaneC[((S_BLOCK1 - aIndex + 4940U)) & S_BLOCK1], 21U) ^ RotL64(aPoisonLaneB[((S_BLOCK1 - aIndex + 8046U)) & S_BLOCK1], 3U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCross, 23U) ^ RotL64(aPrevious, 3U)) ^ (RotL64(aIngress, 35U) + RotL64(aCarry, 50U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterA = ((aWandererH + RotL64(aPrevious, 57U)) + 0x55BFACC9AB1D2615ULL) + aKeyRotateAOrbiterAssignSaltB[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterB = (aWandererB + RotL64(aScatter, 19U)) + 0xAA23F485E61FC88DULL;
            aOrbiterI = ((aWandererG + RotL64(aIngress, 5U)) + RotL64(aCarry, 37U)) + 0x31A80D105A3B07E5ULL;
            aOrbiterE = (((aWandererI + RotL64(aCross, 27U)) + RotL64(aCarry, 57U)) + 0xE77D20FB2BD2809DULL) + aKeyRotateAOrbiterAssignSaltF[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterD = ((aWandererJ + RotL64(aScatter, 35U)) + RotL64(aCarry, 21U)) + 0xDCD14CFDA536A660ULL;
            aOrbiterC = (aWandererD + RotL64(aPrevious, 13U)) + 0xF0BE291DD5EAAEFAULL;
            aOrbiterG = (aWandererC + RotL64(aIngress, 48U)) + 0xEEC83A98E26220A7ULL;
            //
            aOrbiterA = (aOrbiterA + aOrbiterB) + 0x9966985465A91542ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterA) ^ 0x7E6D884D4D8520B5ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x4699CACEF57E76C3ULL), 35U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterD) + 0xF4B7CC8F7094C499ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0xE5675FDE5C670D93ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xAC57D4D9235B5D9DULL), 27U);
