            aOrbiterG = RotL64((aOrbiterG * 0x08ADF19680F1E903ULL), 3U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0xE592F442975D6FAEULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterD) ^ 0xCE86D88A8986F963ULL) ^ aKeyRotateAOrbiterUpdateSaltF[((aIndex + 9U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xAF459612CD17869DULL), 51U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterI) + 0x15BD9CD98E5A53FAULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterG) ^ 0x17555704B7E5D269ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xEA39D4BB98C3B317ULL), 11U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterC) + 0xE6BA7B826351E9E0ULL) + aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterI) ^ 0x9464E74125D0B567ULL) ^ aKeyRotateAOrbiterUpdateSaltC[((aIndex + 8U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x3F1B96DAFA78EEE1ULL), 21U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterE) + 0xAAED9C203F57BCC2ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterB) ^ 0xF33944ECED2A0D21ULL) ^ aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x86EC7052B03D2FA1ULL), 57U);
            //
            aIngress = RotL64(aOrbiterE, 35U) ^ aOrbiterC;
            aIngress = aIngress + (RotL64(aOrbiterD, 5U) ^ aOrbiterA);
            aIngress = aIngress + (RotL64(aOrbiterI, 27U) ^ aOrbiterG);
            aIngress = aIngress + RotL64(aOrbiterB, 60U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererI = aWandererI ^ (((RotL64(aPrevious, 43U) + RotL64(aOrbiterD, 47U)) + aOrbiterB) + aKeyRotateAWandererUpdateSaltE[(((31U - aIndex) + 3U)) & S_SALT1]);
            aWandererG = aWandererG + ((((RotL64(aCross, 57U) + aOrbiterG) + RotL64(aOrbiterB, 41U)) + RotL64(aCarry, 39U)) + aKeyRotateAWandererUpdateSaltD[((aIndex + 28U)) & S_SALT1]);
            aWandererB = aWandererB ^ ((RotL64(aIngress, 23U) + aOrbiterB) + RotL64(aOrbiterA, 60U));
            aWandererC = aWandererC + (((RotL64(aScatter, 37U) + RotL64(aOrbiterA, 11U)) + aOrbiterC) + RotL64(aCarry, 11U));
            aWandererD = aWandererD ^ ((RotL64(aCross, 3U) + aOrbiterB) + RotL64(aOrbiterE, 53U));
            aWandererH = aWandererH + ((RotL64(aIngress, 12U) + RotL64(aOrbiterA, 27U)) + aOrbiterI);
            aWandererJ = aWandererJ ^ ((RotL64(aPrevious, 51U) + aOrbiterC) + RotL64(aOrbiterI, 35U));
