            aIngress = TwistMix64::DiffuseA((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aFuseLaneA[((S_BLOCK1 - aIndex + 20723U)) & S_BLOCK1], 13U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 19607U)) & S_BLOCK1], 58U));
            aCross ^= (RotL64(aShadowLaneD[((S_BLOCK1 - aIndex + 17995U)) & S_BLOCK1], 23U) ^ RotL64(aShadowLaneB[((S_BLOCK1 - aIndex + 24391U)) & S_BLOCK1], 35U));
            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 43U) ^ RotL64(aCarry, 10U)) + (RotL64(aIngress, 27U) + RotL64(aCross, 57U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterA = (aWandererB + RotL64(aIngress, 57U)) + 0x0D07245219FB0F7CULL;
            aOrbiterK = (((aWandererA + RotL64(aCross, 29U)) + RotL64(aCarry, 57U)) + 0x0576F523981ABE1AULL) + aKeyRotateAOrbiterAssignSaltD[((aIndex + 7U)) & S_SALT1];
            aOrbiterD = (((aWandererJ + RotL64(aPrevious, 14U)) + RotL64(aCarry, 21U)) + 0xFCB623B238980B44ULL) + aKeyRotateAOrbiterAssignSaltC[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterG = (aWandererE + RotL64(aScatter, 23U)) + 0x58B0A55E6349B0C6ULL;
            aOrbiterF = ((aWandererI + RotL64(aIngress, 37U)) + RotL64(aCarry, 39U)) + 0x0B7897EBED03B71EULL;
            aOrbiterJ = (aWandererF + RotL64(aScatter, 51U)) + 0xF7EE83055602B8D6ULL;
            aOrbiterE = (aWandererD + RotL64(aCross, 3U)) + 0xD40A5875A52DCA8FULL;
            //
            aOrbiterA = ((aOrbiterA + aOrbiterK) + 0xDDF241D53E7533B8ULL) + aKeyRotateAOrbiterUpdateSaltD[((aIndex + 6U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0x87BF2CC2E1421A24ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x724A6066E1EEEF05ULL), 43U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterF) + 0x6E799E8756C739C8ULL) + aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterG) ^ 0x9E44F10D4268EB7DULL) ^ aKeyRotateAOrbiterUpdateSaltA[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x1DD178F4E26C55A1ULL), 29U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterJ) + 0xD4C6B17860F79AB6ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0x71347F4AB7B34B4FULL;
            aOrbiterE = RotL64((aOrbiterE * 0x61B9ADFCB2BC32DDULL), 23U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterA) + 0x92D88E6ED364B1DBULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterF) ^ 0xC50BA4A71A87A58CULL) ^ aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xEA04421A571E7391ULL), 35U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0x20203B959A6F6974ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0x2F5F74ED0C81C42DULL;
            aOrbiterG = RotL64((aOrbiterG * 0x4B321CC7CECB8E9BULL), 11U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterD) + 0x1BD6558B99166CF0ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0x60BADC57A9C7CCFDULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xC0BEBDAA6537E0F3ULL), 51U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x7E9B47124CEA529DULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterE) ^ 0x633383E767609F2DULL;
            aOrbiterF = RotL64((aOrbiterF * 0xAC11BE85CDEE6085ULL), 3U);
            //
            aIngress = RotL64(aOrbiterJ, 58U) ^ aOrbiterG;
            aIngress = aIngress + (RotL64(aOrbiterA, 41U) ^ aOrbiterE);
