            aWandererB = aWandererB ^ (((RotL64(aIngress, 29U) + RotL64(aOrbiterD, 27U)) + aOrbiterG) + aKeyRotateAWandererUpdateSaltB[((aIndex + 17U)) & S_SALT1]);
            aWandererI = aWandererI + ((RotL64(aCross, 57U) + RotL64(aOrbiterD, 51U)) + aOrbiterJ);
