            aCross = (RotL64(aFuseLaneB[((S_BLOCK1 - aIndex + 26920U)) & S_BLOCK1], 39U) ^ RotL64(aWoodLaneD[((S_BLOCK1 - aIndex + 32261U)) & S_BLOCK1], 20U));
            aCross ^= (RotL64(aEarthLaneD[((S_BLOCK1 - aIndex + 32226U)) & S_BLOCK1], 29U) ^ RotL64(aMagmaLaneB[((S_BLOCK1 - aIndex + 30030U)) & S_BLOCK1], 11U));
            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aIngress, 36U) ^ RotL64(aCarry, 57U)) ^ (RotL64(aCross, 21U) + RotL64(aPrevious, 5U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterI = (aWandererE + RotL64(aScatter, 47U)) + 0x57E4309D78D49C66ULL;
            aOrbiterG = ((aWandererD + RotL64(aIngress, 3U)) + RotL64(aCarry, 35U)) + 0x2209A382FDBFA5F8ULL;
            aOrbiterB = ((aWandererH + RotL64(aCross, 36U)) + RotL64(aCarry, 57U)) + 0xE9F08C97E8D90264ULL;
            aOrbiterE = (((aWandererB + RotL64(aPrevious, 11U)) + RotL64(aCarry, 13U)) + 0x28BE2EDAF4CBD424ULL) + aKeyRotateAOrbiterAssignSaltF[(((31U - aIndex) + 18U)) & S_SALT1];
            aOrbiterC = ((aWandererK + RotL64(aScatter, 53U)) + 0x249A15E96BD11899ULL) + aKeyRotateAOrbiterAssignSaltB[((aIndex + 27U)) & S_SALT1];
            aOrbiterD = (aWandererG + RotL64(aPrevious, 19U)) + 0xC0E1BEDD96EA29D0ULL;
            aOrbiterH = (aWandererF + RotL64(aCross, 27U)) + 0xB71D6B5692BDF3C6ULL;
            //
            aOrbiterI = (aOrbiterI + aOrbiterG) + 0xEAD5451BA3EDBE4CULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterI) ^ 0xC277D2992C883896ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xC451831AC9A8DBDBULL), 3U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0x4152363B93341BDAULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterE) ^ 0x5C39290EF2E5E2F6ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x120AE96963641221ULL), 13U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x83D02CAA887EF20CULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterB) ^ 0xCDD58EC52A44D292ULL) ^ aKeyRotateAOrbiterUpdateSaltC[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x902F989F796E4BEFULL), 57U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterD) + 0x55210763C75AB5A8ULL) + aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterC) ^ 0xDE594FE982310A08ULL) ^ aKeyRotateAOrbiterUpdateSaltA[((aIndex + 19U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xFA284A4ECCE3EC91ULL), 41U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterB) + 0x781A423C7B1D2E91ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0x4D66EE9BED80B8B8ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x62E862646094DDD9ULL), 21U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterH) + 0xBAA528C80E43ABD1ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0xFDBBD565EB2BF02CULL;
            aOrbiterE = RotL64((aOrbiterE * 0x4F845A4B7D127729ULL), 35U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterE) + 0x836A57CDCC706950ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterH) ^ 0x4D855A289A4B04D1ULL) ^ aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xD8D37EFBC454BF8DULL), 29U);
            //
            aIngress = aOrbiterH ^ RotL64(aOrbiterI, 29U);
            aIngress = aIngress + (aOrbiterB ^ RotL64(aOrbiterE, 21U));
            aIngress = aIngress + (aOrbiterC ^ RotL64(aOrbiterG, 11U));
            aIngress = aIngress + RotL64(aOrbiterD, 5U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererK = aWandererK + ((((RotL64(aIngress, 12U) + RotL64(aOrbiterI, 39U)) + aOrbiterB) + RotL64(aCarry, 43U)) + aKeyRotateAWandererUpdateSaltD[(((31U - aIndex) + 16U)) & S_SALT1]);
            aWandererB = aWandererB ^ ((RotL64(aCross, 51U) + RotL64(aOrbiterG, 29U)) + aOrbiterE);
            aWandererE = aWandererE + (((RotL64(aScatter, 37U) + RotL64(aOrbiterE, 23U)) + aOrbiterC) + RotL64(aCarry, 21U));
            aWandererG = aWandererG ^ ((RotL64(aPrevious, 57U) + RotL64(aOrbiterH, 11U)) + aOrbiterD);
            aWandererH = aWandererH + ((RotL64(aCross, 29U) + RotL64(aOrbiterD, 47U)) + aOrbiterB);
            aWandererF = aWandererF ^ (((RotL64(aScatter, 3U) + aOrbiterH) + RotL64(aOrbiterE, 3U)) + aKeyRotateAWandererUpdateSaltE[((aIndex + 7U)) & S_SALT1]);
            aWandererD = aWandererD + ((RotL64(aIngress, 43U) + RotL64(aOrbiterI, 60U)) + aOrbiterH);
            //
            aCarry = aCarry + (aWandererB ^ RotL64(aWandererE, 57U));
